require_once __DIR__.'/../includes/functions.php';require_role(['admin']);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);if($id&&$id!==current_user()['id']){$q=$pdo->prepare('UPDATE users SET is_active=1-is_active WHERE id=? AND role<>\'admin\'');$q->execute([$id]);flash('success','User access status updated.');}else flash('error','The administrator account cannot be changed here.');redirect('users.php');}$users=$pdo->query('SELECT id,name,email,role,locality,is_active,created_at FROM users ORDER BY created_at DESC')->fetchAll();$page_title='Manage users | SharePlate';require __DIR__.'/../includes/header.php';?>
<section class="page-hero compact"><div class="container"><p class="eyebrow">Administration</p><h1>User management</h1><div class="admin-nav"><a href="dashboard.php">Overview</a><a href="users.php">Users</a><a href="donations.php">Donations & reports</a><a href="requests.php">Requests</a></div></div></section><section class="container section"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Locality</th><th>Joined</th><th>Access</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e(ucfirst($u['role']))?></td><td><?=e($u['locality'])?></td><td><?=e(format_datetime($u['created_at']))?></td><td><?=$u['is_active']?'Active':'Disabled'?></td><td><?php if($u['role']!=='admin'):?><form method="post" data-confirm="Change this user's access status?"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=$u['id']?>"><button class="link-button"><?=$u['is_active']?'Deactivate':'Reactivate'?></button></form><?php else:?>Protected<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>